/* Base Variables & Reset */
:root {
  --primary: #F02D00;
  --dark: #171717;
  --dark-hover: #262626;
  --light: #FFFFFF;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-800: #1F2937;
  --gray-900: #111827;
  --accent-green: #00FF66;
  --accent-teal: #00E5FF;

  --font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --border-radius: 8px;
  --transition: 0.3s ease;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--gray-50);
  color: var(--dark);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a {
  text-decoration: none;
  color: inherit;
  transition: color var(--transition);
}

img {
  max-width: 100%;
  display: block;
}

ul {
  list-style: none;
}

button, input {
  font-family: inherit;
  border: none;
  background: none;
  outline: none;
}

button {
  cursor: pointer;
}

/* Layout */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

.flex { display: flex; }
.flex-col { display: flex; flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.justify-center { justify-content: center; }
.gap-2 { gap: 8px; }
.gap-4 { gap: 16px; }
.gap-6 { gap: 24px; }
.gap-8 { gap: 32px; }
.grid { display: grid; }
.grid-cols-2 { grid-template-columns: repeat(2, 1fr); }
.grid-cols-3 { grid-template-columns: repeat(3, 1fr); }
.grid-cols-4 { grid-template-columns: repeat(4, 1fr); }
.hidden { display: none !important; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px 24px;
  border-radius: var(--border-radius);
  font-weight: 600;
  font-size: 16px;
  transition: all var(--transition);
  text-align: center;
}
.btn-primary {
  background-color: var(--primary);
  color: var(--light);
}
.btn-primary:hover {
  background-color: #d12700;
}
.btn-dark {
  background-color: var(--dark);
  color: var(--light);
}
.btn-dark:hover {
  background-color: var(--dark-hover);
}
.btn-outline {
  border: 2px solid var(--dark);
  color: var(--dark);
}
.btn-outline:hover {
  background-color: var(--dark);
  color: var(--light);
}

/* Badges */
.badge {
  display: inline-block;
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.badge-accent {
  background-color: var(--accent-green);
  color: var(--dark);
}
.badge-dark {
  background-color: var(--dark);
  color: var(--light);
}
.badge-discount {
  background-color: #FFF3F0;
  color: var(--primary);
  border: 1px solid rgba(240, 45, 0, 0.2);
}

/* Top Banner */
.promo-banner {
  background-color: var(--dark);
  color: var(--light);
  padding: 12px 0;
  text-align: center;
  font-size: 14px;
  font-weight: 500;
  position: relative;
}
.promo-banner .close-banner {
  position: absolute;
  right: 24px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--gray-300);
  background: transparent;
  border: none;
  cursor: pointer;
}
.promo-banner.dismissed {
  display: none;
}

/* Header */
header {
  background-color: var(--light);
  border-bottom: 1px solid var(--gray-200);
  position: sticky;
  top: 0;
  z-index: 100;
}
.nav-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}
.brand-logo {
  font-size: 24px;
  font-weight: 800;
  color: var(--dark);
  letter-spacing: -0.5px;
}
.brand-logo span {
  color: var(--primary);
}
.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
  font-weight: 600;
  font-size: 15px;
}
.nav-links a:hover {
  color: var(--primary);
}
.nav-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}
.search-bar {
  display: flex;
  align-items: center;
  background-color: var(--gray-100);
  border-radius: 24px;
  padding: 8px 16px;
}
.search-bar input {
  background: transparent;
  border: none;
  outline: none;
  padding-left: 8px;
  font-size: 14px;
  width: 200px;
}

/* Typography */
h1, h2, h3, h4 {
  color: var(--dark);
  font-weight: 800;
  letter-spacing: -0.02em;
}
.h1 { font-size: 48px; line-height: 1.1; margin-bottom: 24px; }
.h2 { font-size: 36px; line-height: 1.2; margin-bottom: 24px; }
.h3 { font-size: 24px; line-height: 1.3; margin-bottom: 16px; }

/* Sections */
section {
  padding: 80px 0;
}

/* Cards */
.card {
  background: var(--light);
  border-radius: var(--border-radius);
  overflow: hidden;
  box-shadow: var(--shadow);
  transition: transform var(--transition), box-shadow var(--transition);
  display: flex;
  flex-direction: column;
}
.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}
.card-img {
  height: 200px;
  background-color: var(--gray-200);
  background-size: cover;
  background-position: center;
  position: relative;
}
.card-content {
  padding: 20px;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}
.card-title {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 8px;
  line-height: 1.3;
}
.card-meta {
  font-size: 14px;
  color: var(--gray-800);
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 12px;
}
.card-price-wrap {
  margin-top: auto;
  display: flex;
  align-items: flex-end;
  gap: 8px;
}
.price-new {
  font-size: 24px;
  font-weight: 800;
  color: var(--dark);
}
.price-old {
  font-size: 14px;
  text-decoration: line-through;
  color: var(--gray-800);
}

/* Carousels */
.carousel-wrap {
  position: relative;
  overflow: hidden;
  margin: -10px;
  padding: 10px;
}
.carousel-track {
  display: flex;
  gap: 24px;
  transition: transform 0.4s cubic-bezier(0.25, 0.8, 0.25, 1);
}
.carousel-item {
  flex: 0 0 calc(33.333% - 16px);
}
.carousel-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  background: var(--light);
  border-radius: 50%;
  box-shadow: var(--shadow);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 10;
  border: 1px solid var(--gray-200);
}
.carousel-nav:hover {
  background: var(--dark);
  color: var(--light);
}
.carousel-prev { left: -20px; }
.carousel-next { right: -20px; }

/* Hero Carousel */
.hero-carousel {
  background-color: var(--dark);
  color: var(--light);
  padding: 60px 0;
  overflow: hidden;
}
.hero-track {
  display: flex;
  transition: transform 0.5s ease;
}
.hero-slide {
  flex: 0 0 100%;
  padding: 0 24px;
}
.hero-content-box {
  background-color: var(--gray-900);
  border-radius: var(--border-radius);
  padding: 40px;
  border: 1px solid var(--gray-800);
}

/* Footer */
footer {
  background-color: var(--light);
  border-top: 1px solid var(--gray-200);
  padding: 60px 0 24px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 60px;
}
.footer-col h4 {
  font-size: 16px;
  margin-bottom: 20px;
}
.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.footer-col a {
  color: var(--gray-800);
  font-size: 14px;
}
.footer-col a:hover {
  color: var(--primary);
}
.footer-bottom {
  border-top: 1px solid var(--gray-200);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
  color: var(--gray-800);
}

/* Accordions */
.accordion-item {
  border-bottom: 1px solid var(--gray-200);
}
.accordion-header {
  padding: 24px 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
  font-size: 18px;
  font-weight: 600;
}
.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
  color: var(--gray-800);
}
.accordion-content p {
  padding-bottom: 24px;
}
.accordion-item.active .accordion-content {
  max-height: 500px;
}
.accordion-icon {
  transition: transform 0.3s ease;
}
.accordion-item.active .accordion-icon {
  transform: rotate(45deg);
}

/* Masonry */
.masonry-grid {
  column-count: 3;
  column-gap: 24px;
}
.masonry-item {
  break-inside: avoid;
  margin-bottom: 24px;
  border-radius: var(--border-radius);
  overflow: hidden;
  position: relative;
  box-shadow: var(--shadow);
}
.masonry-item img {
  width: 100%;
  display: block;
}
.masonry-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  background: linear-gradient(to top, rgba(0,0,0,0.8), transparent);
  padding: 20px;
  color: var(--light);
  opacity: 0;
  transition: opacity var(--transition);
}
.masonry-item:hover .masonry-overlay {
  opacity: 1;
}

/* Responsive */
@media (max-width: 1024px) {
  .carousel-item { flex: 0 0 calc(50% - 12px); }
  .grid-cols-4 { grid-template-columns: repeat(2, 1fr); }
  .masonry-grid { column-count: 2; }
}
@media (max-width: 768px) {
  .nav-links { display: none; }
  .grid-cols-3, .grid-cols-4 { grid-template-columns: 1fr; }
  .carousel-item { flex: 0 0 100%; }
  .footer-grid { grid-template-columns: 1fr; gap: 0; }
  .footer-col h4 { 
    padding: 16px 0; 
    margin: 0; 
    border-bottom: 1px solid var(--gray-200);
    display: flex;
    justify-content: space-between;
    cursor: pointer;
  }
  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    padding: 0;
  }
  .footer-col.active ul {
    max-height: 500px;
    padding: 16px 0;
  }
  .masonry-grid { column-count: 1; }
  .footer-bottom { flex-direction: column; gap: 16px; text-align: center; }
}

